import { useQuery } from '@tanstack/react-query';

interface Todo {
  id: number;
  title: string;
  completed: boolean;
}

const fetchTodos = async (): Promise<Todo[]> => {
  const res = await fetch('http://localhost:4000/api/todos');
  if (!res.ok) {
    throw new Error('Failed to fetch todos');
  }
  return res.json();
};

export default function TodosQueryPanel() {
  const [filter, setFilter] = React.useState<'all' | 'completed' | 'active'>('all');

  const { data, isLoading, isError, error, refetch } = useQuery<Todo[]>({
    queryKey: ['dummy-todos'],
    queryFn: fetchTodos,
  });

  if (isLoading) {
    return <div className="todos-query-panel loading">Loading todos...</div>;
  }

  if (isError) {
    return (
      <div className="todos-query-panel error">
        <p>Error: {error instanceof Error ? error.message : 'Unknown error'}</p>
        <button onClick={() => refetch()}>Retry</button>
      </div>
    );
  }

  const todos = data ?? [];
  const filtered = todos.filter(todo => {
    if (filter === 'completed') return todo.completed;
    if (filter === 'active') return !todo.completed;
    return true;
  });

  return (
    <div className="todos-query-panel loaded">
      <div className="header">
        <h1>Todos (React Query)</h1>
        <button onClick={() => refetch()}>Refresh todos</button>
      </div>

      <div className="filters">
        <button
          onClick={() => setFilter('all')}
          className={filter === 'all' ? 'active' : ''}
        >
          All
        </button>
        <button
          onClick={() => setFilter('active')}
          className={filter === 'active' ? 'active' : ''}
        >
          Active
        </button>
        <button
          onClick={() => setFilter('completed')}
          className={filter === 'completed' ? 'active' : ''}
        >
          Completed
        </button>
      </div>

      {filtered.length === 0 ? (
        <div className="empty">No todos match this filter.</div>
      ) : (
        <ul className="todo-list">
          {filtered.map(todo => (
            <li key={todo.id} className="todo-item">
              <span className={todo.completed ? 'completed' : ''}>{todo.title}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
